import{z as i,x as n,o as r,c as m,q as h,j as o,D as e,d as t,s,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const w=JSON.parse('{"title":"扫描仪产能会计","description":"","frontmatter":{"title":"扫描仪产能会计","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/scanner-throughput.md","filePath":"litho/scanner-throughput.md","lastUpdated":1791413859000}'),A={name:"litho/scanner-throughput.md"};function d(B,a,T,_,u,c){const p=n("Mermaid");return r(),m("div",null,[a[2]||(a[2]=h('<h1 id="扫描仪产能会计" tabindex="-1">扫描仪产能会计 <a class="header-anchor" href="#扫描仪产能会计" aria-label="Permalink to &quot;扫描仪产能会计&quot;">​</a></h1><div class="epigraph"><p>每小时晶圆数是片周期的倒数；剂量、扫描速度、场数与测量开销进同一条加法，不是镜头「更快」的同义词。</p><footer>—— 据 ASML 对扫描机产能（wph）与剂量–速度关系的公开表述整理，不编机型产量</footer></div><p><a href="/litho/dose-control">上一课</a>把晶圆面剂量锁进传感器闭环，并留下一句：目标剂量高，要么降扫描速度，要么要更强的脉冲。缺口是把这句话写成片周期会计。本课钉 wph。故意走焦扩窗留给<a href="/litho/focus-drilling">下一课</a>，不在这里改焦轴。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>剂量环保证 \\(E\\) 进窗。产能问的是：进窗的这一场，整片要多久。单位是 wafers per hour（wph），即 \\(3600/T_\\mathrm{wafer}\\)。\\(T_\\mathrm{wafer}\\) 至少含：装卸与台交换、对准与调平、每个曝光场的步进稳定、以及狭缝扫过场长的时间。上一课的 \\(E\\propto v^{-1}\\int I\\,\\mathrm{d}y&#39;\\) 在这里变成约束：剂量设定升高，扫描速度 \\(v\\) 往往下降，曝光项变长。</p><p><span class="marginnote">术语翻译：wph（wafers per hour）就是「这台机器一小时送走多少片」，是片周期的倒数：一片花 60 秒，wph 就是 60；片周期翻倍，wph 就腰斩。</span></p><p>把 wph 写成「光源功率」一个数，会漏掉场数、步进、双台测量是否被曝光盖住。把宣传册某一机型的峰值 wph 抄到所有层，又忽略了该数字总是在指定剂量、指定场尺寸、指定片尺寸下测的。缺口是会计恒等式，不是再调一次衰减器。</p><h3 id="指定剂量才有-wph" tabindex="-1">指定剂量才有 wph <a class="header-anchor" href="#指定剂量才有-wph" aria-label="Permalink to &quot;指定剂量才有 wph&quot;">​</a></h3><p>厂商公开产能几乎都带「at \\(X\\,\\mathrm{mJ/cm^2}\\)」。胶钝、EUV 随机要加剂量，会计立刻改。本课不引用、不外推任何具体 wph 或毫焦数当产线事实；只保留这层依赖关系。双工件台把测量与曝光并行，片周期近似 \\(\\max(T_\\mathrm{expose},T_\\mathrm{measure})+T_\\mathrm{swap}\\)，细节已在 <a href="/litho/twinscan-dual-stage">TWINSCAN</a>，本课把它收成开销项，不重讲两张卡盘。</p><p><span class="marginnote">不要把数据表 wph 乘以良率再叫出片。扫描机会计停在「片离开卡盘」；涂胶显影、计量、复工不在 \\(T_\\mathrm{wafer}\\) 里。本课也不编某代厂的每小时出片。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把片周期拆开写，而不是估一个总秒数：</p> \\[T_\\mathrm{wafer}\\approx T_\\mathrm{oh}+N_\\mathrm{f}\\,(T_\\mathrm{step}+T_\\mathrm{scan}). \\]<p>\\(T_\\mathrm{oh}\\) 含装片、交换、全局对准一类不随场数线性涨的项；\\(N_\\mathrm{f}\\) 是场数；\\(T_\\mathrm{scan}\\) 是场长除以 \\(v\\)，而 \\(v\\) 受剂量与脉冲能量上限约束。缩小场、减场数、降剂量、提高可用光功率，是四条不同的杠杆，不能合成「优化扫描机」。</p><p>对账时声明：晶圆直径、场网格、是否边缘场、剂量、是否 focus drilling（下一课会拉长有效曝光）。换胶灵敏度是改 \\(E\\) 从而改 \\(v\\)，不是改镜头 NA。</p><p><span class="marginnote">数字实例：100 个场、每场扫描 0.2 秒、步进稳定 0.05 秒，曝光项就是 \\(100\\times 0.25=25\\) 秒；加装卸对准约 15 秒，片周期 40 秒，wph 约 90。剂量一升、扫速一降，这笔加法立刻变脸。</span></p><h3 id="与套刻、均匀性的耦合" tabindex="-1">与套刻、均匀性的耦合 <a class="header-anchor" href="#与套刻、均匀性的耦合" aria-label="Permalink to &quot;与套刻、均匀性的耦合&quot;">​</a></h3><p>加密对准与调平网格加 \\(T_\\mathrm{measure}\\)。双台下，只要测量仍短于曝光，边际产能代价接近零；单台则线性吃 wph。剂量均匀性与扫描速度也耦合：太快时脉冲数变少，脉间涨落压不下去，上一课的 \\(1/\\sqrt{N}\\) 变差。会计合格不等于窗合格。</p>',18)),(r(),o(l,null,{default:e(()=>[s(p,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E7%9B%AE%E6%A0%87%E5%89%82%E9%87%8F%20E%22%5D%20--%3E%20V%5B%22%E6%89%AB%E6%8F%8F%E9%80%9F%E5%BA%A6%20v%22%5D%0A%20%20V%20--%3E%20TS%5B%22T_scan%22%5D%0A%20%20NF%5B%22%E5%9C%BA%E6%95%B0%20N_f%22%5D%20--%3E%20TW%5B%22%E7%89%87%E5%91%A8%E6%9C%9F%20T_wafer%22%5D%0A%20%20TS%20--%3E%20TW%0A%20%20OH%5B%22%E8%A3%85%E5%8D%B8%20%2F%20%E5%AF%B9%E5%87%86%20%2F%20%E4%BA%A4%E6%8D%A2%22%5D%20--%3E%20TW%0A%20%20TW%20--%3E%20WPH%5B%22wph%20%3D%203600%20%2F%20T%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"每个晶圆点必须在狭缝下积分到目标 \\(E\\)。光源瞬时功率给定时，只能靠停留时间——也就是 \\(v\\)——凑积分。场与场之间还要步进、稳定，扫描投影不是连续一条缝扫完整片。因此产能的物理上限先是「光够不够」，再是「台动得是否跟上」，最后才是「测量是否挡住镜头」。ASML 公开叙事把浸没与 EUV 的产能都绑在指定剂量上，原因在此：光学链路定了到达晶圆的瓦数，胶定了要多少毫焦，两者相除就是最短曝光时间。",-1)),(r(),o(l,null,{default:e(()=>[s(p,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIGHT%5B%22%E7%AC%AC%E4%B8%80%E9%81%93%3A%20%E5%85%89%E5%A4%9F%E4%B8%8D%E5%A4%9F%22%5D%20--%3E%7C%22%E5%8A%9F%E7%8E%87%E4%B8%8D%E8%B6%B3%22%7C%20VDOWN%5B%22%E9%99%8D%E6%89%AB%E9%80%9F%20v%20%E5%87%91%E5%89%82%E9%87%8F%22%5D%0A%20%20STAGE%5B%22%E7%AC%AC%E4%BA%8C%E9%81%93%3A%20%E5%8F%B0%E5%8A%A8%E5%BE%97%E8%B7%9F%E4%B8%8D%E8%B7%9F%22%5D%20--%3E%20STEP%5B%22%E6%AD%A5%E8%BF%9B%E4%B8%8E%E7%A8%B3%E5%AE%9A%E6%97%B6%E9%97%B4%22%5D%0A%20%20MEAS%5B%22%E7%AC%AC%E4%B8%89%E9%81%93%3A%20%E6%B5%8B%E9%87%8F%E6%8C%A1%E4%B8%8D%E6%8C%A1%E9%95%9C%E5%A4%B4%22%5D%20--%3E%20DUAL%5B%22%E5%8F%8C%E5%8F%B0%E5%B9%B6%E8%A1%8C%E5%8F%AF%E8%A2%AB%E6%9B%9D%E5%85%89%E9%81%AE%E4%BD%8F%22%5D%0A%20%20VDOWN%20--%3E%20TW%5B%22%E7%89%87%E5%91%A8%E6%9C%9F%20T_wafer%22%5D%0A%20%20STEP%20--%3E%20TW%0A%20%20DUAL%20--%3E%20TW%0A%20%20TW%20--%3E%20WPH%5B%22wph%20%3D%203600%20%2F%20T_wafer%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=h('<p>EUV 还要计膜透过、收集器寿命对可用功率的侵蚀；那是后课光源与膜，本课只把它们记成「可用 \\(I\\) 下降 → 同一 \\(E\\) 下 \\(v\\) 下降」。不要在这里编源功率瓦数。</p><p><span class="marginnote">同一台机，植入层低剂量与关键金属高剂量可以差出完全不同的 wph。层策略会计要按层加，不能用关键层的表值代表整条流水线。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写任何机型的出厂 wph，不把公开演示场尺寸当成你厂的 tape-out 网格。也不讨论轨道涂胶节拍——那是另一台设备的 \\(T\\)。Focus drilling 会把一场拆成一段焦上的积分，等效曝光项变长，下一课再把这笔记到窗上，本课的公式形式仍适用，只是 \\(T_\\mathrm{scan}\\) 或场次数增加。</p><p>复工、送计量、换掩模的准备时间不属于扫描仪内部会计，却会吃车间产能。把 wph 直接当 FAB 产出，是类别错误。</p><p><span class="marginnote">常见误区：把数据表上的峰值 wph 直接当车间产出。它是在指定剂量、指定场尺寸下测的「片离开卡盘」速度；涂胶显影、量测、复工都在外面，拿它排产会系统性高估。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>wph 是片周期的倒数；片周期是开销、场数、步进与扫描之和。</li><li>剂量经扫描速度进入会计；公开产能必须带剂量条件。</li><li>双台并行的是测量与曝光，不是两个镜头。</li><li>不编机型 wph、不编厂级出片；只保留恒等式与杠杆。</li><li>走焦会拉长曝光项，下一课再写入窗的取舍。</li><li>出处：ASML 对扫描机产能与剂量条件的公开关系；Levinson 对曝光时间与产线节拍的讨论。</li></ul>',8))])}const D=i(A,[["render",d]]);export{w as __pageData,D as default};
